prediction_sql:
SELECT DISTINCT winner_name
FROM matches
WHERE year = 2013;

SELECT AVG(CAST(Horsepower AS REAL)) AS average_horsepower
FROM cars_data
WHERE Year < 80;

SELECT AVG(CAST(Horsepower AS REAL)) AS average_horsepower
FROM cars_data
WHERE Year > 80 AND Horsepower GLOB '[0-9]*';

SELECT "AirportCode", "AirportName"
FROM "airports"
WHERE "City" = 'Anthony';

SELECT Language, COUNT(*) AS channel_count
FROM TV_Channel
GROUP BY Language;

SELECT Language, COUNT(*) AS channel_count
FROM TV_Channel
GROUP BY Language;

SELECT DISTINCT zip_postcode
FROM Addresses
WHERE city = 'Port Chelsea';

SELECT song.Title, singer.Name
FROM song
JOIN singer ON song.Singer_ID = singer.Singer_ID;

SELECT song.Title, singer.first_name, singer.last_name
FROM song
JOIN singer ON song.Singer_ID = singer.Singer_ID;

SELECT t.date_of_treatment, p.first_name
FROM Treatments AS t
JOIN Professionals AS p ON p.professional_id = t.professional_id;

SELECT SUM(SurfaceArea) AS total_surface_area
FROM country
WHERE Continent IN ('Antarctica', 'Europe');

SELECT PetType, AVG(weight) AS average_weight
FROM Pets
GROUP BY PetType;

SELECT "Name", "Location"
FROM "stadium"
WHERE "Capacity" BETWEEN 5000 AND 10000;

SELECT department_description
FROM Departments
WHERE LOWER(department_name) LIKE '%the computer%';

SELECT SUM("SurfaceArea") AS total_surface_area
FROM "country"
WHERE "Region" = 'Caribbean';

SELECT SUM("SurfaceArea") AS total_area
FROM "country"
WHERE "Region" = 'Caribbean';

SELECT "Language", COUNT(*) AS channel_count
FROM "TV_Channel"
GROUP BY "Language";

SELECT "Language", COUNT(*) AS channel_count
FROM "TV_Channel"
GROUP BY "Language";

SELECT MAX(weight) AS max_weight, PetType
FROM Pets
GROUP BY PetType;

SELECT PetType, MAX(weight) AS heaviest_weight
FROM Pets
GROUP BY PetType;

SELECT p.Name
FROM people AS p
JOIN poker_player AS pp ON pp.People_ID = p.People_ID;

SELECT people.Name
FROM people
JOIN poker_player ON people.ppl_id = poker_player.ppl_id;

SELECT DISTINCT CountryCode
FROM countrylanguage
WHERE Language <> 'English';

SELECT "Episode"
FROM "TV_series"
ORDER BY CAST("Rating" AS REAL) DESC;

SELECT "Pixel_aspect_ratio_PAR", "Country"
FROM "TV_Channel"
WHERE "Language" <> 'English';
